import { execFileSync } from "node:child_process";
import { writeFileSync } from "node:fs";

const repo = "indkhan/Moneo";
const gh = path => JSON.parse(execFileSync("gh", ["api", path], { encoding: "utf8", maxBuffer: 64 << 20 }));
const setupStep = /^(Set up job|Run actions\/checkout|Run actions\/setup-node|Run actions\/cache|Run npm ci|Start the test backend|Run npx playwright install|Fetch the native backend|Linux dependencies|Check release version|Pull the backend|Run npm run qa:auth|Wait for the QA app)/;
const secs = (a, b) => (Date.parse(b) - Date.parse(a)) / 1000;
const pct = (xs, p) => { if (!xs.length) return NaN; const s = [...xs].sort((a, b) => a - b); return s[Math.min(s.length - 1, Math.ceil(p / 100 * s.length) - 1)]; };

const runs = [];
for (let page = 1; runs.length < 150; page++) {
  const batch = gh(`repos/${repo}/actions/runs?per_page=100&page=${page}`).workflow_runs;
  if (!batch.length) break;
  runs.push(...batch.filter(r => r.status === "completed" && ["CI", "Desktop"].includes(r.name) && r.conclusion !== "skipped"));
}
const rows = [];
for (const run of runs.slice(0, 150)) {
  const { jobs } = gh(`repos/${repo}/actions/runs/${run.id}/attempts/${run.run_attempt}/jobs?per_page=100`);
  for (const job of jobs) {
    if (!job.started_at || !job.completed_at || job.conclusion === "skipped") continue;
    let setup = 0, running = 0;
    for (const step of job.steps ?? []) {
      if (!step.started_at || !step.completed_at) continue;
      const d = secs(step.started_at, step.completed_at);
      if (setupStep.test(step.name) || step.name.startsWith("Post ") || step.name === "Complete job") setup += d; else running += d;
    }
    rows.push({ workflow: run.name, event: run.event, run: run.id, job: job.name.replace(/^cache .*/, "cache"), conclusion: job.conclusion,
      waiting: secs(job.created_at, job.started_at), setup, running, total: secs(job.created_at, job.completed_at) });
  }
  rows.push({ workflow: run.name, event: run.event, run: run.id, job: "(whole run)", conclusion: run.conclusion, total: secs(run.created_at, run.updated_at) });
}
writeFileSync(process.argv[2], JSON.stringify(rows));
const groups = Map.groupBy(rows, r => `${r.workflow} / ${r.job}`);
console.log("workflow / job | n | wait p50 p95 | setup p50 p95 | run p50 p95 | total p50 p95 (s)");
for (const [key, list] of [...groups].sort()) {
  const f = k => list.map(r => r[k]).filter(x => x != null);
  const cell = k => f(k).length ? `${pct(f(k), 50).toFixed(0)} ${pct(f(k), 95).toFixed(0)}` : "- -";
  console.log(`${key} | ${list.length} | ${cell("waiting")} | ${cell("setup")} | ${cell("running")} | ${cell("total")}`);
}
const fail = rows.filter(r => r.job !== "(whole run)" && r.conclusion === "failure");
console.log(`\nfailed jobs: ${fail.length}`, Object.fromEntries(Map.groupBy(fail, r => `${r.workflow}/${r.job}`).entries().map(([k, v]) => [k, v.length])));
console.log(`runs: ${runs.slice(0, 150).length}, from ${runs.at(Math.min(149, runs.length - 1))?.created_at} to ${runs[0]?.created_at}`);

